def _parse_version(v):
    parts = v.strip().split('.')
    if len(parts) != 3:
        raise ValueError(f"Malformed version: {v}")
    result = []
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Malformed version: {v}")
        result.append(int(p))
    return tuple(result)


def satisfies(version: str, spec: str) -> bool:
    ver = _parse_version(version)

    spec = spec.strip()
    if not spec:
        raise ValueError("Malformed spec: empty")

    if spec.startswith('^'):
        base = _parse_version(spec[1:])
        major, minor, patch = base
        if major > 0:
            lower = base
            upper = (major + 1, 0, 0)
        elif minor > 0:
            lower = base
            upper = (0, minor + 1, 0)
        else:
            lower = base
            upper = (0, 0, patch + 1)
        return lower <= ver < upper

    if spec.startswith('~'):
        base = _parse_version(spec[1:])
        major, minor, patch = base
        lower = base
        upper = (major, minor + 1, 0)
        return lower <= ver < upper

    tokens = spec.split()
    ops = ['>=', '<=', '>', '<', '=']
    comparators = []
    for tok in tokens:
        matched = False
        for op in ops:
            if tok.startswith(op):
                ver_str = tok[len(op):]
                if not ver_str:
                    raise ValueError(f"Malformed spec: {spec}")
                comparators.append((op, _parse_version(ver_str)))
                matched = True
                break
        if not matched:
            # assume exact version with no operator (only valid if single token)
            comparators.append(('=', _parse_version(tok)))
    if not comparators:
        raise ValueError(f"Malformed spec: {spec}")

    for op, cver in comparators:
        if op == '>=':
            if not (ver >= cver):
                return False
        elif op == '<=':
            if not (ver <= cver):
                return False
        elif op == '>':
            if not (ver > cver):
                return False
        elif op == '<':
            if not (ver < cver):
                return False
        elif op == '=':
            if not (ver == cver):
                return False
    return True
